import "influxdata/influxdb/schema"
import "experimental"
import "array"

getOrDefault = (f, d) => if exists f then f else d

// Aggregate request counts per group
data_request = from(bucket: "default_agg_topic_2")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
      |> filter(fn: (r) => (r._field == "prompt_tokens" or r._field == "completion_tokens" or r._field == "topic_count" or r._field == "price" ) )
         |> filter(fn: (r) => exists r.title)
         //|> filter(fn: (r) => (r.title != "undefined"))
          |> filter(fn: (r) => (r.topic != ""))
    |> schema.fieldsAsCols()
 |> group(columns: ["title","model"])
    |> reduce(
        fn: (r, accumulator) => ({
          topic_count: getOrDefault(f: r.topic_count, d: 0) + accumulator.topic_count,
          prompt_tokens: getOrDefault(f: r.prompt_tokens, d: 0) + accumulator.prompt_tokens,
          completion_tokens: getOrDefault(f: r.completion_tokens, d: 0) + accumulator.completion_tokens,
          price: getOrDefault(f: r.price, d: 0.0) + accumulator.price
        }),
        identity: {topic_count: 0, prompt_tokens: 0, completion_tokens: 0, price:0.0}
    )

|> filter(fn: (r) => (r.model != ""))


// Determine the top model per title
top_models = data_request
  //|> filter(fn: (r) => (r.model != ""))
  |> group(columns: ["title"])
  |> top(n: 1, columns: ["topic_count"])
  |> keep(columns: ["title", "model"])
  |> map(fn: (r) => ({
      title: r.title,
      model_top: r.model
  }))

// Merge top model information into the main dataset
result = join(
  tables: {data: data_request, top: top_models},
  on: ["title"]
)
|> group(columns: ["title","model_top"])
    |> reduce(
        fn: (r, accumulator) => ({
          topic_count: getOrDefault(f: r.topic_count, d: 0) + accumulator.topic_count,
          prompt_tokens: getOrDefault(f: r.prompt_tokens, d: 0) + accumulator.prompt_tokens,
          completion_tokens: getOrDefault(f: r.completion_tokens, d: 0) + accumulator.completion_tokens,
          price: getOrDefault(f: r.price, d: 0.0) + accumulator.price
        }),
        identity: {topic_count: 0, prompt_tokens: 0, completion_tokens: 0, price:0.0}
    )



result
 |> group()
